begin;
create temporary table daytrail_collab_checks(label text primary key);
grant select,insert on daytrail_collab_checks to anon,authenticated;
create or replace function pg_temp.check_true(label text,actual boolean) returns void language plpgsql as $$
begin if actual is distinct from true then raise exception 'Failed: %',label; end if; insert into daytrail_collab_checks values(label); end; $$;
create or replace function pg_temp.expect_error(label text,statement text,expected_state text) returns void language plpgsql as $$
begin begin execute statement; exception when others then if sqlstate<>expected_state then raise exception 'Failed: % (expected %, got %: %)',label,expected_state,sqlstate,sqlerrm; end if; insert into daytrail_collab_checks values(label); return; end; raise exception 'Failed: % (unexpected success)',label; end; $$;
create or replace function pg_temp.actor(n integer) returns uuid language sql as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;$$;
create or replace function pg_temp.mid(n integer) returns uuid language sql as $$select ('10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;$$;
create or replace function pg_temp.trip() returns jsonb language sql as $$
select '{"id":"collabtest","name":"Shared holiday","destination":"Tokyo","startDate":"2026-10-27","timezone":"Asia/Tokyo","ideas":[],"customPlaces":{},"flights":[{"id":"f1","fromPlaceId":"nijo","toPlaceId":"gion","departure":{"date":"2026-10-27","time":"12:30","timezone":"Europe/London"},"arrival":{"date":"2026-10-28","time":"10:00","timezone":"Asia/Tokyo"},"bookingReference":"OWNER-FLIGHT-SECRET","privateNotes":"Private flight note","departureGate":"PRIVATE-GATE"}],"stays":[{"id":"s1","placeId":"hotel","checkInDate":"2026-10-27","checkOutDate":"2026-10-30","timezone":"Asia/Tokyo","bookingReference":"OWNER-STAY-SECRET","contact":"Owner contact","bookingUrl":"https://example.com/secret","privateNotes":"Private stay note"}],"days":[{"id":"d1","label":"Day 1","date":"Tue 27","title":"Fly","startPlaceId":"nijo","endPlaceId":"hotel","endStayId":"s1","endMode":"transit","items":[{"aid":"a1","placeId":"gion","duration":0,"fixed":null,"mode":"flight","note":"Shared note","flightId":"f1"}]},{"id":"d2","label":"Day 2","date":"Wed 28","title":"Tokyo","startStayId":"s1","endMode":"walk","items":[]}]}'::jsonb;
$$;
create temporary table fixtures(key text primary key,value jsonb);
grant select,insert,update on fixtures to authenticated;
create or replace function pg_temp.cloud() returns uuid language sql as $$select (value->>'cloud_trip_id')::uuid from fixtures where key='enabled';$$;
create or replace function pg_temp.doc() returns jsonb language sql as $$select public.daytrail_collab_get(auth.uid(),pg_temp.cloud())->'document';$$;
create or replace function pg_temp.rev() returns bigint language sql as $$select (public.daytrail_collab_get(auth.uid(),pg_temp.cloud())->>'revision')::bigint;$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
(pg_temp.actor(1),'owner@example.com',now(),'{"full_name":"Owner"}'),
(pg_temp.actor(2),'editor@example.com',now(),'{"full_name":"Editor"}'),
(pg_temp.actor(3),'viewer@example.com',now(),'{"full_name":"Viewer"}'),
(pg_temp.actor(4),'outsider@example.com',now(),'{}'),
(pg_temp.actor(5),'unverified@example.com',null,'{}');
select set_config('request.jwt.claim.sub',pg_temp.actor(1)::text,true);
set local role authenticated;
select pg_temp.check_true('owner creates private trip',public.daytrail_mutate_trip(pg_temp.actor(1),'collabtest',0,pg_temp.mid(1),'create',pg_temp.trip(),2)->>'status'='ok');
select public.daytrail_mutate_travel_mark(pg_temp.actor(1),'collabtest','flight:f1','gion','done',0,pg_temp.mid(2));
select pg_temp.check_true('private trip not in collaboration library',public.daytrail_collab_list(pg_temp.actor(1))='[]'::jsonb);
select pg_temp.check_true('stale enable conflicts',public.daytrail_collab_enable(pg_temp.actor(1),'collabtest',99)->>'status'='conflict');
insert into fixtures values('enabled',public.daytrail_collab_enable(pg_temp.actor(1),'collabtest',1)->'trip');
select pg_temp.check_true('enable increments revision',(select value->>'revision'='2' from fixtures where key='enabled'));
select pg_temp.check_true('owner receives private flight',pg_temp.doc()->'flights'->0->>'bookingReference'='OWNER-FLIGHT-SECRET');
select pg_temp.check_true('owner receives private stay',pg_temp.doc()->'stays'->0->>'contact'='Owner contact');
select pg_temp.check_true('enable idempotent',public.daytrail_collab_enable(pg_temp.actor(1),'collabtest',1)->'trip'->>'revision'='2');
select pg_temp.check_true('direct owner read is redacted',(select not(document::text like '%OWNER-%') and not(document::text like '%PRIVATE-GATE%') from public.daytrail_trips where trip_id='collabtest'));
select pg_temp.check_true('owner legacy progress copied',public.daytrail_collab_list_travel_marks(pg_temp.actor(1),pg_temp.cloud())->0->>'state'='done');
select pg_temp.expect_error('legacy save blocked',$$select public.daytrail_mutate_trip(pg_temp.actor(1),'collabtest',2,pg_temp.mid(3),'save',pg_temp.trip(),2)$$,'0A000');
select pg_temp.expect_error('legacy replay blocked',$$select public.daytrail_mutate_trip(pg_temp.actor(1),'collabtest',0,pg_temp.mid(1),'create',pg_temp.trip(),2)$$,'0A000');
select pg_temp.expect_error('legacy delete blocked',$$select public.daytrail_mutate_trip(pg_temp.actor(1),'collabtest',2,pg_temp.mid(4),'delete',null,2)$$,'0A000');
select pg_temp.expect_error('private table inaccessible',$$select * from daytrail_private.booking_secrets$$,'42501');
select pg_temp.expect_error('private function inaccessible',$$select daytrail_private.mutate_private_trip_v2(pg_temp.actor(1),'collabtest',2,pg_temp.mid(4),'delete',null,2)$$,'42501');
select pg_temp.expect_error('account mismatch',$$select public.daytrail_collab_list(pg_temp.actor(2))$$,'42501');
insert into fixtures values('editor_invite',public.daytrail_collab_invite(pg_temp.actor(1),pg_temp.cloud(),'  EDITOR@example.com  ','editor'));
insert into fixtures values('viewer_invite',public.daytrail_collab_invite(pg_temp.actor(1),pg_temp.cloud(),'viewer@example.com','viewer'));
select pg_temp.check_true('invite email normalized',(select value->>'email'='editor@example.com' from fixtures where key='editor_invite'));
select pg_temp.check_true('invite token high entropy',(select length(value->>'token')=64 from fixtures where key='editor_invite'));
select pg_temp.check_true('invite expires seven days',(select (value->>'expires_at')::timestamptz=now()+interval '7 days' from fixtures where key='editor_invite'));
select pg_temp.check_true('people does not expose tokens',not(public.daytrail_collab_people(pg_temp.actor(1),pg_temp.cloud())::text like '%token%'));
select pg_temp.expect_error('invalid role rejected',$$select public.daytrail_collab_invite(pg_temp.actor(1),pg_temp.cloud(),'new@example.com','owner')$$,'22023');
select pg_temp.expect_error('owner self invite rejected',$$select public.daytrail_collab_invite(pg_temp.actor(1),pg_temp.cloud(),'owner@example.com','viewer')$$,'22023');
select set_config('request.jwt.claim.sub',pg_temp.actor(4)::text,true);
select pg_temp.check_true('outsider cannot list trip',public.daytrail_collab_list(pg_temp.actor(4))='[]'::jsonb);
select pg_temp.expect_error('outsider cannot read',$$select public.daytrail_collab_get(pg_temp.actor(4),pg_temp.cloud())$$,'42501');
select pg_temp.expect_error('wrong account cannot accept',$$select public.daytrail_collab_accept(pg_temp.actor(4),(select value->>'token' from fixtures where key='editor_invite'))$$,'42501');
select pg_temp.expect_error('bad token rejected',$$select public.daytrail_collab_accept(pg_temp.actor(4),'bad')$$,'22023');
select set_config('request.jwt.claim.sub',pg_temp.actor(2)::text,true);
insert into fixtures values('editor_joined',public.daytrail_collab_accept(pg_temp.actor(2),(select value->>'token' from fixtures where key='editor_invite')));
select pg_temp.check_true('editor joined with editor role',(select value->>'role'='editor' from fixtures where key='editor_joined'));
select pg_temp.check_true('editor cannot read private flight',not(pg_temp.doc()->'flights'->0 ?| array['bookingReference','privateNotes','departureGate','arrivalGate']));
select pg_temp.check_true('editor cannot read private stay',not(pg_temp.doc()->'stays'->0 ?| array['bookingReference','privateNotes','contact','bookingUrl']));
select pg_temp.check_true('shared ordinary note retained',pg_temp.doc()->'days'->0->'items'->0->>'note'='Shared note');
select pg_temp.check_true('editor has no direct trip read',(select count(*)=0 from public.daytrail_trips));
select pg_temp.check_true('editor accept idempotent',public.daytrail_collab_accept(pg_temp.actor(2),(select value->>'token' from fixtures where key='editor_invite'))->>'role'='editor');
select pg_temp.check_true('editor sees trip in library',jsonb_array_length(public.daytrail_collab_list(pg_temp.actor(2)))=1);
select pg_temp.check_true('editor cannot see pending email invitations',public.daytrail_collab_people(pg_temp.actor(2),pg_temp.cloud())->'invitations'='[]'::jsonb);
select pg_temp.check_true('editor travel starts empty',public.daytrail_collab_list_travel_marks(pg_temp.actor(2),pg_temp.cloud())='[]'::jsonb);
select pg_temp.expect_error('editor cannot invite',$$select public.daytrail_collab_invite(pg_temp.actor(2),pg_temp.cloud(),'other@example.com','viewer')$$,'42501');
select pg_temp.expect_error('editor cannot manage members',$$select public.daytrail_collab_member(pg_temp.actor(2),pg_temp.cloud(),pg_temp.actor(1),null)$$,'42501');
select pg_temp.expect_error('editor cannot delete',$$select public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),2,pg_temp.mid(5),'delete')$$,'42501');
select pg_temp.expect_error('editor cannot submit owner secrets',$$select public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),2,pg_temp.mid(6),'save',pg_temp.trip())$$,'42501');
insert into fixtures values('editor_save',jsonb_set(pg_temp.doc(),'{days,1,title}','"Edited Tokyo"'));
select pg_temp.check_true('editor save accepted',public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),2,pg_temp.mid(7),'save',(select value from fixtures where key='editor_save'))->'trip'->>'revision'='3');
select pg_temp.check_true('stale snapshot conflicts',public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),2,pg_temp.mid(8),'save',jsonb_set(pg_temp.doc(),'{name}','"Stale"'))->>'status'='conflict');
select pg_temp.check_true('conflict includes redacted document',not(public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),2,pg_temp.mid(8),'save',pg_temp.doc())->'trip'->'document'->'flights'->0 ? 'bookingReference'));
select pg_temp.check_true('second editor save accepted',public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),3,pg_temp.mid(9),'save',jsonb_set(pg_temp.doc(),'{name}','"Latest name"'))->'trip'->>'revision'='4');
insert into fixtures values('replay',public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),2,pg_temp.mid(7),'save',(select value from fixtures where key='editor_save')));
select pg_temp.check_true('lost ack returns original committed revision',(select value->>'committed_revision'='3' and value->>'replayed'='true' from fixtures where key='replay'));
select pg_temp.check_true('lost ack returns latest trip',(select value->'trip'->>'revision'='4' and value->'trip'->'document'->>'name'='Latest name' from fixtures where key='replay'));
select pg_temp.expect_error('receipt token cannot reuse different payload',$$select public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),2,pg_temp.mid(7),'save',pg_temp.doc())$$,'22023');
select pg_temp.expect_error('invalid compound references rejected',$$select public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),4,pg_temp.mid(10),'save',jsonb_set(pg_temp.doc(),'{flights}','[]'))$$,'22023');
select set_config('request.jwt.claim.sub',pg_temp.actor(3)::text,true);
select public.daytrail_collab_accept(pg_temp.actor(3),(select value->>'token' from fixtures where key='viewer_invite'));
select pg_temp.check_true('viewer can read shared doc',pg_temp.doc()->>'name'='Latest name');
select pg_temp.expect_error('viewer cannot save',$$select public.daytrail_collab_mutate(pg_temp.actor(3),pg_temp.cloud(),4,pg_temp.mid(11),'save',pg_temp.doc())$$,'42501');
select pg_temp.check_true('viewer personal progress allowed',public.daytrail_collab_mutate_travel_mark(pg_temp.actor(3),pg_temp.cloud(),'flight:f1','gion','done',0,pg_temp.mid(12))->'mark'->>'revision'='1');
select pg_temp.check_true('progress leaves itinerary unchanged',pg_temp.rev()=4);
select pg_temp.check_true('personal travel stale conflicts',public.daytrail_collab_mutate_travel_mark(pg_temp.actor(3),pg_temp.cloud(),'flight:f1','gion','skipped',0,pg_temp.mid(13))->>'status'='conflict');
select pg_temp.expect_error('progress validates location',$$select public.daytrail_collab_mutate_travel_mark(pg_temp.actor(3),pg_temp.cloud(),'flight:f1','nijo','done',1,pg_temp.mid(14))$$,'22023');
select pg_temp.expect_error('progress validates target',$$select public.daytrail_collab_mutate_travel_mark(pg_temp.actor(3),pg_temp.cloud(),'flight:missing','gion','done',0,pg_temp.mid(15))$$,'22023');
select public.daytrail_collab_mutate_travel_mark(pg_temp.actor(3),pg_temp.cloud(),'flight:f1','gion','skipped',1,pg_temp.mid(16));
select pg_temp.check_true('travel replay survives later save',public.daytrail_collab_mutate_travel_mark(pg_temp.actor(3),pg_temp.cloud(),'flight:f1','gion','done',0,pg_temp.mid(12))->'mark'->>'revision'='1');
select pg_temp.check_true('travel replay does not roll back latest',public.daytrail_collab_list_travel_marks(pg_temp.actor(3),pg_temp.cloud())->0->>'state'='skipped');
select pg_temp.check_true('activity contains no booking fields',not(public.daytrail_collab_activity(pg_temp.actor(3),pg_temp.cloud())::text like '%OWNER-%'));
select set_config('request.jwt.claim.sub',pg_temp.actor(1)::text,true);
select pg_temp.check_true('editor saves preserved owner secrets',pg_temp.doc()->'flights'->0->>'bookingReference'='OWNER-FLIGHT-SECRET');
select pg_temp.check_true('other progress does not overwrite owner',public.daytrail_collab_list_travel_marks(pg_temp.actor(1),pg_temp.cloud())->0->>'state'='done');
select pg_temp.check_true('owner updates private field',public.daytrail_collab_mutate(pg_temp.actor(1),pg_temp.cloud(),4,pg_temp.mid(17),'save',jsonb_set(pg_temp.doc(),'{flights,0,bookingReference}','"NEW-OWNER-SECRET"'))->'trip'->'document'->'flights'->0->>'bookingReference'='NEW-OWNER-SECRET');
select pg_temp.expect_error('owner cannot leave',$$select public.daytrail_collab_leave(pg_temp.actor(1),pg_temp.cloud())$$,'22023');
select pg_temp.expect_error('owner cannot downgrade themselves',$$select public.daytrail_collab_member(pg_temp.actor(1),pg_temp.cloud(),pg_temp.actor(1),'viewer')$$,'22023');
insert into fixtures values('epoch_before',public.daytrail_collab_get(pg_temp.actor(1),pg_temp.cloud())->'channel_epoch');
select public.daytrail_collab_member(pg_temp.actor(1),pg_temp.cloud(),pg_temp.actor(2),'viewer');
select pg_temp.check_true('permission change rotates channel',(select public.daytrail_collab_get(pg_temp.actor(1),pg_temp.cloud())->'channel_epoch'<>value from fixtures where key='epoch_before'));
select set_config('request.jwt.claim.sub',pg_temp.actor(2)::text,true);
select pg_temp.expect_error('downgrade blocks even accepted retry',$$select public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),2,pg_temp.mid(7),'save',(select value from fixtures where key='editor_save'))$$,'42501');
select pg_temp.check_true('old channel rejected',not public.daytrail_collab_can_receive('daytrail:'||pg_temp.cloud()::text||':'||(select value #>> '{}' from fixtures where key='epoch_before')));
select pg_temp.check_true('new channel allowed',public.daytrail_collab_can_receive('daytrail:'||pg_temp.cloud()::text||':'||(public.daytrail_collab_get(pg_temp.actor(2),pg_temp.cloud())->>'channel_epoch')));
select set_config('request.jwt.claim.sub',pg_temp.actor(1)::text,true);
select public.daytrail_collab_member(pg_temp.actor(1),pg_temp.cloud(),pg_temp.actor(2),null);
select set_config('request.jwt.claim.sub',pg_temp.actor(2)::text,true);
select pg_temp.check_true('removed member disappears from library',public.daytrail_collab_list(pg_temp.actor(2))='[]'::jsonb);
select pg_temp.expect_error('removed cannot read',$$select public.daytrail_collab_get(pg_temp.actor(2),pg_temp.cloud())$$,'42501');
select pg_temp.expect_error('removed cannot reuse accepted invite',$$select public.daytrail_collab_accept(pg_temp.actor(2),(select value->>'token' from fixtures where key='editor_invite'))$$,'22023');
select pg_temp.expect_error('removed cannot read personal progress',$$select public.daytrail_collab_list_travel_marks(pg_temp.actor(2),pg_temp.cloud())$$,'42501');
select set_config('request.jwt.claim.sub',pg_temp.actor(1)::text,true);
insert into fixtures values('cancelled',public.daytrail_collab_invite(pg_temp.actor(1),pg_temp.cloud(),'outsider@example.com','editor'));
select public.daytrail_collab_cancel_invite(pg_temp.actor(1),pg_temp.cloud(),(select (value->>'id')::uuid from fixtures where key='cancelled'));
insert into fixtures values('expired',public.daytrail_collab_invite(pg_temp.actor(1),pg_temp.cloud(),'outsider@example.com','editor'));
insert into fixtures values('unverified',public.daytrail_collab_invite(pg_temp.actor(1),pg_temp.cloud(),'unverified@example.com','editor'));
reset role;
update daytrail_private.invites set expires_at=now()-interval '1 second' where id=(select (value->>'id')::uuid from fixtures where key='expired');
