select set_config('request.jwt.claim.sub',pg_temp.actor(1)::text,true);
select pg_temp.check_true('owner restore accepted',public.daytrail_collab_mutate(pg_temp.actor(1),pg_temp.cloud(),6,pg_temp.mid(19),'restore')->'trip'->>'deleted_at' is null);
select pg_temp.check_true('restore retains private sidecar',pg_temp.doc()->'flights'->0->>'bookingReference'='NEW-OWNER-SECRET');
