select pg_temp.expect_error('left viewer cannot replay travel write',$$select public.daytrail_collab_mutate_travel_mark(pg_temp.actor(3),pg_temp.cloud(),'flight:f1','gion','done',0,pg_temp.mid(12))$$,'42501');
select set_config('request.jwt.claim.sub',pg_temp.actor(1)::text,true);
insert into fixtures values('fresh_editor_invite',public.daytrail_collab_invite(pg_temp.actor(1),pg_temp.cloud(),'editor@example.com','editor'));
