select pg_temp.check_true('new invitation restores access',public.daytrail_collab_get(pg_temp.actor(2),pg_temp.cloud())->>'role'='editor');
insert into fixtures values('before_remove_bookings',pg_temp.doc());
select public.daytrail_collab_mutate(pg_temp.actor(2),pg_temp.cloud(),pg_temp.rev(),pg_temp.mid(20),'save',jsonb_set(jsonb_set(jsonb_set(jsonb_set(pg_temp.doc(),'{flights}','[]'),'{stays}','[]'),'{days,0}',((pg_temp.doc()->'days'->0)-'endStayId')||'{"items":[]}'::jsonb),'{days,1}',(pg_temp.doc()->'days'->1)-'startStayId'));
