select pg_temp.expect_error('unknown current schema field rejected',$$select public.daytrail_collab_mutate(pg_temp.actor(1),pg_temp.cloud(),pg_temp.rev(),pg_temp.mid(22),'save',pg_temp.doc()||'{"admin":true}'::jsonb)$$,'22023');
select pg_temp.check_true('ordinary private trip protocol retained',public.daytrail_mutate_trip(pg_temp.actor(1),'privateagain',0,pg_temp.mid(23),'create',jsonb_set(pg_temp.trip(),'{id}','"privateagain"'),2)->>'status'='ok');
select pg_temp.check_true('private trip list remains separate',jsonb_array_length(public.daytrail_collab_list(pg_temp.actor(1)))=1);
