select pg_temp.check_true('same document ID another owner gets distinct cloud ID',public.daytrail_collab_enable(pg_temp.actor(4),'collabtest',1)->'trip'->>'cloud_trip_id'<>pg_temp.cloud()::text);
select pg_temp.check_true('library does not confuse same document IDs',jsonb_array_length(public.daytrail_collab_list(pg_temp.actor(4)))=1);
select pg_temp.expect_error('cannot spoof actor in progress',$$select public.daytrail_collab_list_travel_marks(pg_temp.actor(1),pg_temp.cloud())$$,'42501');
select set_config('realtime.topic','daytrail:'||pg_temp.cloud()::text||':'||(select value #>> '{}' from fixtures where key='epoch_before'),true);
select pg_temp.check_true('Realtime RLS denies former channel',(select count(*)=0 from realtime.messages));
reset role;
set local role anon;
select pg_temp.expect_error('anonymous RPC unavailable',$$select public.daytrail_collab_list(pg_temp.actor(1))$$,'42501');
reset role;
select count(*) as passed_collaboration_checks from daytrail_collab_checks;
rollback;
